import type {
  Difficulty,
  Goal,
  Language,
  Resource,
  ResourceType,
  SourceKind,
} from "@/lib/types";
import { subjectById } from "@/data/subjects";

/**
 * DEMO DIRECTORY
 * --------------
 * External links either open an official site (NCERT / CBSE Academic / DIKSHA / ExamFear)
 * or a YouTube search for the topic.
 */

export const OFFICIAL_SITES = {
  ncert: "https://ncert.nic.in/",
  cbse: "https://cbseacademic.nic.in/",
  diksha: "https://diksha.gov.in/",
  examfear: "https://www.examfear.com/",
} as const;

const yt = (q: string) =>
  `https://www.youtube.com/results?search_query=${encodeURIComponent(q)}`;

const c = (s: string, i: number) => `${s}-c${i}`;

interface Opts {
  recommended?: boolean;
  daysAgo?: number;
  views?: number;
  url?: string;
}

let seq = 0;

const R = (
  title: string,
  subjectId: string,
  chapterId: string | null,
  type: ResourceType,
  source: string,
  sourceKind: SourceKind,
  language: Language,
  difficulty: Difficulty,
  goal: Goal,
  duration: number | null,
  description: string,
  opts: Opts = {},
): Resource => {
  seq += 1;
  const short = subjectById(subjectId)?.short ?? "";
  return {
    id: `res-${String(seq).padStart(3, "0")}`,
    title,
    subjectId,
    chapterId,
    type,
    source,
    sourceKind,
    language,
    difficulty,
    goal,
    duration,
    description,
    url:
      opts.url ??
      (sourceKind === "youtube"
        ? yt(`${title} ${short} class 12`)
        : `https://example.com/studynest12/${subjectId}/${String(seq).padStart(3, "0")}`),
    recommended: opts.recommended ?? false,
    addedAt: new Date(Date.now() - (opts.daysAgo ?? 21) * 86400000).toISOString(),
    views: opts.views ?? 9200,
  };
};

